_HIDE = re.compile(r'-20\d\d-\d\d-\d\d|-\d{4}$|:|(?:^|-)(?:realtime|audio|image|transcribe|tts|live|instruct)(?:-|$)|embedding|moderation|dall-e|whisper|davinci|babbage|sora|computer-use|search-(?:api|preview)|deep-research')
_LEGACY = re.compile(r'^(?:gpt-4|gpt-3\.5|claude-[23]-)')

def _current(provider, mid, legacy=False):
    "Whether a listed id belongs in a picker; older generations only when `legacy`."
    return bool(re.search(r'\d', mid or '')) and not _HIDE.search(mid) and (legacy or not _LEGACY.match(mid))

# %% ../nbs/01b_models.ipynb #ca5783b2
def provider_models(p, legacy=False, ttl=300):
    "Ids a picker offers for provider `p`: the curated ones in their order, then what live discovery adds. The live list is kept on disk, so a new process shows the last one at once and asks again in the background."
    from ramabana.core import probed
    src = next((q for q, f in LIVE.items() if f is LIVE.get(p)), p)
    try: live = probed(f'{src}-models', lambda: LIVE[p](), ttl=ttl) if p in LIVE else []
    except Exception: live = []
    newest = lambda m: (tuple(map(int, re.findall(r'\d+', m))), m)
    live = (m for m in live if _current(p, m, legacy) and not re.search(r'-20\d{6}$', m))
    return list(dict.fromkeys([*CATALOG.get(p, ()), *sorted(live, key=newest, reverse=True)]))

# %% ../nbs/01b_models.ipynb #404e1ed5
_DROP = re.compile(r'^(?:mlx|gguf|it|litert|lm|optiq|instruct|\d+bit)$', re.I)
_DATE = re.compile(r'-20\d{6}$|-20\d\d-\d\d-\d\d$')   # a snapshot date at the end, not a part of the name

def _words(m):
    "The words of one model id: `gpt-6-astra` gives `GPT-6 Astra`, `Qwen3-4B` gives `Qwen 3 4B`; OpenAI's `o4-mini` stays."
    ts = [t for t in re.split(r'[-_:\s]+', _DATE.sub('', m)) if t and not _DROP.match(t)]
    if ts and re.fullmatch(r'o\d+', ts[0], re.I): return '-'.join(t.lower() for t in ts)
    out = []
    for t in ts:
        if t.isdigit() and out and re.fullmatch(r'[\d.]+', out[-1]) and '.' not in out[-1]: out[-1] += '.' + t
        elif out and out[-1] == 'GPT' and re.fullmatch(r'[\d.]+o?', t, re.I): out[-1] += f'-{t.lower()}'
        elif out and re.fullmatch(r'GPT-[\d.]+', out[-1]) and t.lower() == 'o': out[-1] += 'o'   # gpt-4-o-preview
        elif out and re.fullmatch(r'GPT-[\d.]+o', out[-1]): out.append(t.lower())          # GPT-4o mini, as OpenAI writes it
        elif re.fullmatch(r'[a-z]?[\d.]+[bmk]', t, re.I): out.append(t.upper())
        elif t.lower() == 'gpt': out.append('GPT')
        elif re.fullmatch(r'[a-z]\d+', t, re.I): out.append(t.upper())                     # Kimi K3, DeepSeek R1
        else: out.append(re.sub(r'^([A-Za-z]+)(\d)', r'\1 \2', t[0].upper() + t[1:]))
    return ' '.join(out)

def model_label(name, repo=''):
    "A name people know for `name`: `claude-opus-5-5` gives `Claude Opus 5.5`, `qwen3-4b` gives `Qwen 3 4B`. `repo` is a local model's download. A config.toml name stays."
    from ramabana.core import CUSTOM
    name = str(name)
    pre, _, m = name.rpartition('/')
    if name in CUSTOM or pre.split('/')[0] in ('remote', 'azure'): return name
    out = _words(repo.rpartition('/')[2] if repo else m) or name
    return f'Claude {out}' if pre.split('/')[0] in ('claude', 'anthropic') and not out.startswith('Claude') else out

#: the company behind each hosted provider prefix
COMPANIES = dict(claude='Anthropic', anthropic='Anthropic', openai='OpenAI', codex='OpenAI', gemini='Google', copilot='GitHub',
                 azure='Microsoft', openrouter='OpenRouter')

def vendor_of(name):
    "The company that hosts `name` ('Anthropic', 'OpenAI', 'Google', 'GitHub', 'Microsoft'), or '' for a local model or one it cannot tell."
    from ramabana.core import is_azure, resolve
    if (pre := str(name).partition('/')[0]) in COMPANIES and '/' in str(name): return COMPANIES[pre]
    try: spec = resolve(name)
    except Exception: return ''
    if spec.local: return ''
    if is_azure(spec): return 'Microsoft'
    return COMPANIES.get(spec.runtime) or COMPANIES.get(spec.model_id.partition('/')[0], '')
